<?php
/**
 * Local-only HTTP fixture for the four provider APIs.
 * Mounted as a mu-plugin by the three wp-env configurations; excluded from releases.
 */

defined( 'ABSPATH' ) || exit;

// Stable product schema fixture for the acceptance suite. WooCommerce and SEO
// plugins may suppress their own Product graph depending on their version and
// integration settings; this guarantees that Omnium's JSON-LD preservation is
// exercised on every recipe site.
add_action(
	'wp_head',
	static function (): void {
		if ( ! function_exists( 'is_product' ) || ! is_product() ) {
			return;
		}
		$product = function_exists( 'wc_get_product' ) ? wc_get_product( get_queried_object_id() ) : false;
		if ( ! $product || ! str_starts_with( $product->get_slug(), 'recette-v1-produit-' ) ) {
			return;
		}
		$schema = array(
			'@context' => 'https://schema.org',
			'@type'    => 'Product',
			'name'     => $product->get_name(),
			'sku'      => $product->get_sku(),
			'offers'   => array(
				array(
					'@type'         => 'Offer',
					'price'         => wc_format_decimal( $product->get_regular_price(), wc_get_price_decimals() ),
					'priceCurrency' => get_woocommerce_currency(),
				),
			),
		);
		echo '<script type="application/ld+json" data-omtr-fixture="product">' . wp_json_encode( $schema, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ) . '</script>' . "\n"; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- JSON generated by WordPress for a local fixture.
	},
	99
);

add_filter(
	'pre_http_request',
	static function ( $preempt, $args, $url ) {
		$kind = null;
		if ( 'https://api.anthropic.com/v1/messages' === $url ) {
			$kind = 'claude';
		} elseif ( 'https://api.openai.com/v1/responses' === $url ) {
			$kind = 'openai';
		} elseif ( 'https://api.eu.mistral.ai/v1/chat/completions' === $url ) {
			$kind = 'mistral';
		} elseif ( preg_match( '~^https://generativelanguage\.googleapis\.com/v1beta/models/[a-zA-Z0-9._-]+:generateContent$~D', $url ) ) {
			$kind = 'gemini';
		}
		if ( null === $kind ) {
			return $preempt;
		}

		update_option( 'omtr_mock_calls', (int) get_option( 'omtr_mock_calls', 0 ) + 1, false );
		$request = json_decode( (string) ( $args['body'] ?? '' ), true );
		if ( ! is_array( $request ) ) {
			return new WP_Error( 'omtr_mock_bad_request', 'Invalid mock request JSON.' );
		}

		$system = '';
		$user = '';
		switch ( $kind ) {
			case 'claude':
				$system = (string) ( $request['system'] ?? '' );
				$user = (string) ( $request['messages'][0]['content'] ?? '' );
				break;
			case 'openai':
				$system = (string) ( $request['instructions'] ?? '' );
				$user = (string) ( $request['input'] ?? '' );
				break;
			case 'mistral':
				$system = (string) ( $request['messages'][0]['content'] ?? '' );
				$user = (string) ( $request['messages'][1]['content'] ?? $request['messages'][0]['content'] ?? '' );
				break;
			case 'gemini':
				$system = (string) ( $request['systemInstruction']['parts'][0]['text'] ?? '' );
				$user = (string) ( $request['contents'][0]['parts'][0]['text'] ?? '' );
				break;
		}

		$text = 'pong';
		if ( preg_match( '/<segments>\s*(\{.*?\})\s*<\/segments>/s', $user, $matches ) ) {
			$segments = json_decode( $matches[1], true );
			if ( ! is_array( $segments ) ) {
				return new WP_Error( 'omtr_mock_bad_segments', 'Invalid mock segments.' );
			}

			// Simulate a provider plan whose real input limit is lower than
			// the plugin's conservative batch budget: any batch over 8000
			// source characters is rejected with HTTP 400 "too large".
			$total_chars = 0;
			foreach ( $segments as $source ) {
				$total_chars += strlen( (string) $source );
			}
			if ( $total_chars > 8000 ) {
				return array(
					'headers'  => array( 'content-type' => 'application/json' ),
					'body'     => wp_json_encode( array( 'object' => 'error', 'message' => 'Request too large: input tokens exceed the model limit', 'type' => 'invalid_request_error' ) ),
					'response' => array( 'code' => 400, 'message' => 'Bad Request' ),
					'cookies'  => array(),
					'filename' => null,
				);
			}
			$target = preg_match( '/into language "([a-z-]+)"/i', $system, $target_match ) ? strtolower( $target_match[1] ) : 'en';
			$words  = str_starts_with( $target, 'es' )
				? array(
					'À propos'     => 'Acerca de',
					'Présentation de notre atelier et de ses services' => 'Presentación de nuestro taller y sus servicios',
					'Atelier de céramique artisanale à Lyon' => 'Taller de cerámica artesanal en Lyon',
					'Donnez de l’élan à vos idées' => 'Dé impulso a sus ideas',
					'Produit de recette ' => 'Producto de prueba ',
					'Recette'      => 'Prueba',
					'publique'     => 'pública',
					'numéro'       => 'número',
					'Présentation' => 'Presentación',
					'notre'        => 'nuestro',
					'atelier'      => 'taller',
					'produit'      => 'producto',
					'Description'  => 'Descripción',
					'française'    => 'francesa',
				)
				: array(
					'À propos'     => 'About',
					'Présentation de notre atelier et de ses services' => 'Presentation of our workshop and its services',
					'Atelier de céramique artisanale à Lyon' => 'Artisanal ceramics workshop in Lyon',
					'Donnez de l’élan à vos idées' => 'Give momentum to your ideas',
					'Produit de recette ' => 'Acceptance product ',
					'Recette'      => 'Acceptance test',
					'publique'     => 'public',
					'numéro'       => 'number',
					'Présentation' => 'Presentation',
					'notre'        => 'our',
					'atelier'      => 'workshop',
					'produit'      => 'product',
					'Description'  => 'Description',
					'française'    => 'French',
				);
			$translated = array();
			foreach ( $segments as $number => $source ) {
				// Deterministic local vocabulary: enough to validate that visible text
				// changes without artificial [EN]/[ES] markers or an external API.
				$candidate = strtr( (string) $source, $words );
				if ( $candidate === $source && preg_match_all( '/[\p{L}\p{N}]+/u', strip_tags( (string) $source ) ) >= 2 ) {
					$candidate = ( str_starts_with( $target, 'es' ) ? 'Traducido: ' : 'Translated: ' ) . $candidate;
				}
				$translated[ (string) $number ] = $candidate;
			}
			$text = wp_json_encode( $translated, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES );
		}

		switch ( $kind ) {
			case 'claude':
				$body = array( 'content' => array( array( 'type' => 'text', 'text' => $text ) ) );
				break;
			case 'openai':
				$body = array( 'output' => array( array( 'type' => 'message', 'content' => array( array( 'type' => 'output_text', 'text' => $text ) ) ) ) );
				break;
			case 'mistral':
				$body = array( 'choices' => array( array( 'message' => array( 'content' => $text ) ) ) );
				break;
			default:
				$body = array( 'candidates' => array( array( 'content' => array( 'parts' => array( array( 'text' => $text ) ) ) ) ) );
		}

		return array(
			'headers'  => array( 'content-type' => 'application/json' ),
			'body'     => wp_json_encode( $body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ),
			'response' => array( 'code' => 200, 'message' => 'OK' ),
			'cookies'  => array(),
			'filename' => null,
		);
	},
	10,
	3
);
